  if(['modalBg','modalText'].includes(key)) return shell(`
    <div class="mpModalBackdrop"><div class="mpModal${target('modalBg')}" style="background:${color('modalBg','#fff')};color:${color('modalText','#28232b')}"><div class="mpModalTitle ${targetText('modalText')}">360 ml</div><div class="mpChoice ${targetText('modalText')}">Colher e canudinho? ○ Sim ○ Não</div><div class="mpChoice">Complementos</div><div class="mpButton" style="background:${color('buttonBg','#712489')};color:${color('buttonText','#fff')}">Adicionar</div></div></div>`, '#ece7ee');

